function uniquePathsWithObstacles(grid) {
  const R = grid.length
  if (R === 0) return 0
  const C = grid[0].length
  if (grid[0][0] === 1 || grid[R - 1][C - 1] === 1) return 0
  const dp = Array.from({ length: R }, () => new Array(C).fill(0))
  dp[0][0] = 1
  for (let r = 0; r < R; r++) {
    for (let c = 0; c < C; c++) {
      if (grid[r][c] === 1) {
        dp[r][c] = 0
      } else if (r > 0 || c > 0) {
        dp[r][c] = (r > 0 ? dp[r - 1][c] : 0) + (c > 0 ? dp[r][c - 1] : 0)
      }
    }
  }
  return dp[R - 1][C - 1]
}

